export const esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const peso=n=>'₱'+Number(n||0).toLocaleString('en-PH');
export const shade=(h,a)=>{const n=parseInt(h.slice(1),16);return '#'+[16,8,0].map(s=>Math.round(((n>>s)&255)*(1-a)).toString(16).padStart(2,'0')).join('')};
export function toast(m){let t=document.getElementById('toast');if(!t){t=document.createElement('div');t.id='toast';document.body.appendChild(t)}
 t.textContent=m;t.style.display='block';clearTimeout(toast.t);toast.t=setTimeout(()=>t.style.display='none',3200)}
export const BACK='<svg viewBox="0 0 24 24" width="24" height="24" aria-hidden="true"><path d="M15 5l-7 7 7 7" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const CARTSVG='<svg viewBox="0 0 24 24" width="26" height="26" aria-hidden="true"><path d="M6 8h12l1 12H5z" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linejoin="round"/><path d="M9 8V7a3 3 0 0 1 6 0v1" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round"/></svg>';
let cnt=0;
export const cartBtn=()=>`<button class="cartbtn" onclick="location.href='cart.html'" aria-label="Cart">${CARTSVG}${cnt?`<b>${cnt}</b>`:''}</button>`;
export function setBadge(n){cnt=n;const b=document.querySelector('.cartbtn');if(!b)return;const o=b.querySelector('b');if(o)o.remove();if(n>0){const e=document.createElement('b');e.textContent=n;b.appendChild(e)}}
export const cartTotalQty=items=>items.reduce((s,x)=>s+x.q,0);
export function initBadge(uid){getCart(uid).then(c=>setBadge(cartTotalQty(c))).catch(()=>{})}

// ---- sign-in ----
export function onUser(cb){return onAuthStateChanged(auth,u=>cb(u?{uid:u.uid,email:u.email||'',name:u.displayName||u.email||'Friend',pic:u.photoURL||'',verified:!!u.emailVerified}:null))}
export function signIn(){const p=new GoogleAuthProvider();p.setCustomParameters({prompt:'select_account'});return signInWithPopup(auth,p)}
export const signOutUser=()=>fbSignOut(auth);
export const isAdmin=u=>!!u&&u.verified&&u.email.toLowerCase()===ADMIN_EMAIL;
// pages that need a signed-in person: sends everyone else back to the sign-in page
export function gate(cb){onUser(u=>{if(!u){location.replace('index.html');return}cb(u)})}

