export const PALETTE=[
 {n:'White',h:'#ffffff'},{n:'Cream',h:'#f2e6d0'},{n:'Beige',h:'#d9c3a0'},{n:'Light gray',h:'#cfcfcf'},{n:'Gray',h:'#8a8a8a'},{n:'Charcoal',h:'#444444'},{n:'Black',h:'#1f1f1f'},
 {n:'Brown',h:'#8b5a3c'},{n:'Camel',h:'#c19a6b'},{n:'Chocolate',h:'#5a3a29'},{n:'Blush',h:'#f4cccc'},{n:'Baby pink',h:'#f8c8dc'},{n:'Dusty rose',h:'#d9a0a0'},{n:'Hot pink',h:'#e75480'},
 {n:'Coral',h:'#f08a7e'},{n:'Peach',h:'#f7c59f'},{n:'Red',h:'#c62828'},{n:'Burgundy',h:'#7b1e3a'},{n:'Terracotta',h:'#c8553d'},{n:'Orange',h:'#f28c28'},{n:'Mustard',h:'#d9a53b'},
 {n:'Yellow',h:'#f6d55c'},{n:'Lemon',h:'#fbf3a0'},{n:'Sage',h:'#9db39a'},{n:'Mint',h:'#b8e0c8'},{n:'Olive',h:'#7d8a4a'},{n:'Forest',h:'#2f5d3a'},{n:'Teal',h:'#2a8c8c'},
 {n:'Sky blue',h:'#9fc5e8'},{n:'Baby blue',h:'#bcd8f0'},{n:'Blue',h:'#3d6fb6'},{n:'Navy',h:'#2b3a5c'},{n:'Lavender',h:'#c8b6e2'},{n:'Lilac',h:'#b497d6'},{n:'Purple',h:'#7a4fa3'},{n:'Plum',h:'#5e2a4f'}];
const defaultCats=()=>[{id:'bags',name:'Bags',image:TOTE_IMG,createdAt:1},{id:'keychains',name:'Keychains',image:'',createdAt:2},{id:'hairclips',name:'Hair Clips',image:'',createdAt:3},{id:'plushies',name:'Plushies',image:'',createdAt:4}];
const defaultTote=()=>({id:'tote',name:'Reversible Tote Bag',category:'bags',price:DEFAULT_TOTE_PRICE,image:TOTE_IMG,designer:true,description:'',options:[{label:'Outside',colors:DEFAULT_COLORS.map((c,i)=>({...c,id:'o'+i}))},{label:'Inside',colors:DEFAULT_COLORS.map((c,i)=>({...c,id:'i'+i}))}],createdAt:Date.now()});
let seeded=null,loadErr='';
export const getLoadError=()=>loadErr;
export const colorGroups=p=>((p&&p.options)||[]).filter(g=>g&&g.colors&&g.colors.length);
export async function isSeeded(){if(seeded!==null)return seeded;try{seeded=(await getDoc(doc(db,'settings','seeded'))).exists()}catch(e){loadErr=e.code||e.message||'unknown error';seeded=false}return seeded}
export async function loadCategories(){
 loadErr='';const sd=await isSeeded();if(!sd)return defaultCats();
 try{return (await getDocs(collection(db,'categories'))).docs.map(d=>({id:d.id,...d.data()})).sort((a,b)=>{
  const pa=a.position!=null?a.position:(a.createdAt||0), pb=b.position!=null?b.position:(b.createdAt||0);
  return pa-pb;
 })}
 catch(e){loadErr=e.code||e.message||'unknown error';return[]}
}
export async function loadProducts(){
 const sd=await isSeeded();let list=[];
 try{list=(await getDocs(collection(db,'products'))).docs.map(d=>({id:d.id,...d.data()}))}catch(e){loadErr=e.code||e.message||'unknown error'}
 if(!sd&&!list.find(p=>p.id==='tote'))list.push(defaultTote());
 return list.sort((a,b)=>{
  const hasA=a.position!=null, hasB=b.position!=null;
  if(hasA&&hasB) return a.position-b.position;
  if(hasA) return -1;
  if(hasB) return 1;
  return (b.createdAt||0)-(a.createdAt||0);
 });
}
export async function getProduct(id){
 const sd=await isSeeded();
 try{const s=await getDoc(doc(db,'products',id));if(s.exists())return {id,...s.data()}}catch(e){loadErr=e.code||e.message||'unknown error'}
 return (!sd&&id==='tote')?defaultTote():null;
}
export const saveProduct=p=>setDoc(doc(db,'products',p.id),JSON.parse(JSON.stringify(p)));
export const deleteProduct=id=>deleteDoc(doc(db,'products',id));
export const saveCategory=c=>setDoc(doc(db,'categories',c.id),JSON.parse(JSON.stringify(c)));
export const deleteCategory=id=>deleteDoc(doc(db,'categories',id));
// ---- one photo per color choice (each saved as its own entry so a product never goes over the size limit) ----
export const newId=()=>'k'+Date.now().toString(36)+Math.random().toString(36).slice(2,6);
export async function loadColorPhotos(pid){const m={};
 try{(await getDocs(query(collection(db,'colorPhotos'),where('pid','==',pid)))).forEach(d=>{const x=d.data();m[x.cid]=x.image})}catch(e){loadErr=e.code||e.message||'unknown error'}
 return m}
export const saveColorPhoto=(pid,cid,image)=>setDoc(doc(db,'colorPhotos',pid+'__'+cid),{pid,cid,image});
export const deleteColorPhoto=(pid,cid)=>deleteDoc(doc(db,'colorPhotos',pid+'__'+cid));
export async function deleteAllColorPhotos(pid){const s=await getDocs(query(collection(db,'colorPhotos'),where('pid','==',pid)));await Promise.all(s.docs.map(d=>deleteDoc(d.ref)))}

// first time the owner opens the admin panel: copy the starting categories and tote into the database so they can be edited or deleted like anything else
export async function seedAll(){
 for(const c of defaultCats()){const r=doc(db,'categories',c.id);if(!(await getDoc(r)).exists())await setDoc(r,JSON.parse(JSON.stringify(c)))}
 const tr=doc(db,'products','tote');if(!(await getDoc(tr)).exists())await setDoc(tr,JSON.parse(JSON.stringify(defaultTote())));
 await setDoc(doc(db,'settings','seeded'),{done:true,at:Date.now()});seeded=true;
}

// ---- carts (saved online under each person's Google account) ----
export async function getCart(uid){const s=await getDoc(doc(db,'carts',uid));return s.exists()?(s.data().items||[]):[]}
export const saveCart=(uid,items)=>setDoc(doc(db,'carts',uid),{items:JSON.parse(JSON.stringify(items))});

// ---- photos: shrink to keep the database small ----
export function resizeImage(file,max=800,q=.78){return new Promise((res,rej)=>{const img=new Image();
 img.onerror=()=>rej(new Error('Could not read that image'));
 img.onload=()=>{const k=Math.min(1,max/Math.max(img.width,img.height)),c=document.createElement('canvas');c.width=Math.round(img.width*k);c.height=Math.round(img.height*k);
  const x=c.getContext('2d');x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(img,0,0,c.width,c.height);
  let out=c.toDataURL('image/jpeg',q),qq=q;while(out.length>700000&&qq>.4){qq-=.1;out=c.toDataURL('image/jpeg',qq)}res(out)};
 img.src=URL.createObjectURL(file)})}
